class AbstractClass {
    virtual void pureVirtualFunction() = 0; // pure virtual function
};

// Usage restrictions:
// - Cannot instantiate objects of AbstractClass
// - Cannot use AbstractClass as a parameter or return type by value
// - Can declare pointers or references to AbstractClass

// Examples:
// AbstractClass obj; // Error: cannot instantiate
// AbstractClass f(); // Error: cannot return by value
// void g(AbstractClass); // Error: parameter by value
// AbstractClass& h(AbstractClass&); // OK: reference parameter
